window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a6c9b7febd62aaa9"]={"versions": [{"id": "FIG-a6c9b7febd62aaa9", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm für das AUTOSAR Diagnostic Extract Template (DEXT). Das Diagramm spezifiziert die metamodellbasierte Modellierung des OBD-Dienstes Mode 0x04 (Clear/Reset Emission-Related Diagnostic Information) im Kontext des Diagnostic Communication Managers (Dcm). Es veranschaulicht die Spezialisierung generischer Diagnosedienst- und Diagnoseklassenstrukturen für spezifische OBD-Dienste sowie deren Verknüpfung zu Zugriffsberechtigungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und deren Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>DiagnosticCommonElement</code>: Abstrakter gemeinsamer Basistyp für Diagnose-Elemente.\n</li><li><code>DiagnosticServiceInstance</code> (spezialisiert <code>DiagnosticCommonElement</code>): Repräsentiert eine konkrete Instanz eines Diagnosedienstes. Besitzt eine gerichtete Assoziation <code>+serviceClass</code> (Kardinalität <code>0..1</code>, Stereotyp «atpAbstract») zur Metaklasse <code>DiagnosticServiceClass</code> sowie eine Assoziation <code>+accessPermission</code> (Kardinalität <code>0..1</code>) zu <code>DiagnosticAccessPermission</code>.\n</li><li><code>DiagnosticServiceClass</code> (spezialisiert <code>DiagnosticCommonElement</code>): Repräsentiert die funktionale Klassendefinition des Diagnosedienstes. Enthält das Attribut <code>+accessPermissionValidity : DiagnosticAccessPermissionValidityEnum</code> und referenziert <code>DiagnosticAccessPermission</code> über die gerichtete Assoziation <code>+accessPermission</code> (Kardinalität <code>0..1</code>).\n</li><li><code>DiagnosticAccessPermission</code> (spezialisiert <code>DiagnosticCommonElement</code>): Definiert die Zugriffsbedingungen für den Dienst.\n</li><li><code>DiagnosticClearResetEmissionRelatedInfo</code> (spezialisiert <code>DiagnosticServiceInstance</code>): Konkrete Modellierungsklasse für eine Instanz des OBD-Modus 0x04. Definiert eine gerichtete Assoziation <code>+clearResetEmissionRelatedDiagnosticInfoClass</code> mit Multiplizität <code>1</code> zur Klasse <code>DiagnosticClearResetEmissionRelatedInfoClass</code>, welche die geerbte Assoziation <code>{redefines serviceClass}</code> redefiniert.\n</li><li><code>DiagnosticClearResetEmissionRelatedInfoClass</code> (spezialisiert <code>DiagnosticServiceClass</code>): Spezifische Serviceklasse für das Löschen bzw. Zurücksetzen emissionsbezogener Diagnoseinformationen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite Modellierung von dynamischen Sequenzen, Zustandsübergängen oder Kontrollflüssen. Das Diagramm beschreibt die Deklarations- und Konfigurationsstruktur eines OBD-Modus 0x04 im AUTOSAR Diagnostic Extract. Der Dienstaufruf im Steuergerät führt über die instanziierte Konfiguration (<code>DiagnosticClearResetEmissionRelatedInfo</code>) zur Dienstklasse (<code>DiagnosticClearResetEmissionRelatedInfoClass</code>), wobei die statische Zuordnung der Berechtigungen über <code>DiagnosticAccessPermission</code> zur Absicherung herangezogen wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der AUTOSAR-DEXT-Metamodellstruktur für OBD Mode 0x04 gemäß <code>[TPS_DEXT_01128]</code>. Die Modellierung erzwingt über die Redefinition <code>{redefines serviceClass}</code> mit Kardinalität <code>1</code>, dass jede Instanz von <code>DiagnosticClearResetEmissionRelatedInfo</code> exakt einer Klasseninstanz <code>DiagnosticClearResetEmissionRelatedInfoClass</code> zugewiesen sein muss. Entwickler und Generatoren von Diagnosekonfigurationen müssen sicherstellen, dass die Typkompatibilität zwischen Service-Instanz und zugehöriger Service-Klasse gewahrt bleibt und Zugriffsprüfungen konsistent mit <code>DiagnosticAccessPermissionValidityEnum</code> parametriert werden.</p>"}, {"id": "FIG-62ebbe518190f195", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm für das AUTOSAR Diagnostic Extract Template (DEXT). Das Diagramm spezifiziert die metamodellbasierte Modellierung des OBD-Dienstes Mode 0x04 (Clear/Reset Emission-Related Diagnostic Information) im Kontext des Diagnostic Communication Managers (Dcm). Es veranschaulicht die Spezialisierung generischer Diagnosedienst- und Diagnoseklassenstrukturen für spezifische OBD-Dienste sowie deren Verknüpfung zu Zugriffsberechtigungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und deren Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>DiagnosticCommonElement</code>: Abstrakter gemeinsamer Basistyp für Diagnose-Elemente.\n</li><li><code>DiagnosticServiceInstance</code> (spezialisiert <code>DiagnosticCommonElement</code>): Repräsentiert eine konkrete Instanz eines Diagnosedienstes. Besitzt eine gerichtete Assoziation <code>+serviceClass</code> (Kardinalität <code>0..1</code>, Stereotyp «atpAbstract») zur Metaklasse <code>DiagnosticServiceClass</code> sowie eine Assoziation <code>+accessPermission</code> (Kardinalität <code>0..1</code>) zu <code>DiagnosticAccessPermission</code>.\n</li><li><code>DiagnosticServiceClass</code> (spezialisiert <code>DiagnosticCommonElement</code>): Repräsentiert die funktionale Klassendefinition des Diagnosedienstes. Enthält das Attribut <code>+accessPermissionValidity : DiagnosticAccessPermissionValidityEnum</code> und referenziert <code>DiagnosticAccessPermission</code> über die gerichtete Assoziation <code>+accessPermission</code> (Kardinalität <code>0..1</code>).\n</li><li><code>DiagnosticAccessPermission</code> (spezialisiert <code>DiagnosticCommonElement</code>): Definiert die Zugriffsbedingungen für den Dienst.\n</li><li><code>DiagnosticClearResetEmissionRelatedInfo</code> (spezialisiert <code>DiagnosticServiceInstance</code>): Konkrete Modellierungsklasse für eine Instanz des OBD-Modus 0x04. Definiert eine gerichtete Assoziation <code>+clearResetEmissionRelatedDiagnosticInfoClass</code> mit Multiplizität <code>1</code> zur Klasse <code>DiagnosticClearResetEmissionRelatedInfoClass</code>, welche die geerbte Assoziation <code>{redefines serviceClass}</code> redefiniert.\n</li><li><code>DiagnosticClearResetEmissionRelatedInfoClass</code> (spezialisiert <code>DiagnosticServiceClass</code>): Spezifische Serviceklasse für das Löschen bzw. Zurücksetzen emissionsbezogener Diagnoseinformationen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite Modellierung von dynamischen Sequenzen, Zustandsübergängen oder Kontrollflüssen. Das Diagramm beschreibt die Deklarations- und Konfigurationsstruktur eines OBD-Modus 0x04 im AUTOSAR Diagnostic Extract. Der Dienstaufruf im Steuergerät führt über die instanziierte Konfiguration (<code>DiagnosticClearResetEmissionRelatedInfo</code>) zur Dienstklasse (<code>DiagnosticClearResetEmissionRelatedInfoClass</code>), wobei die statische Zuordnung der Berechtigungen über <code>DiagnosticAccessPermission</code> zur Absicherung herangezogen wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der AUTOSAR-DEXT-Metamodellstruktur für OBD Mode 0x04 gemäß <code>[TPS_DEXT_01128]</code>. Die Modellierung erzwingt über die Redefinition <code>{redefines serviceClass}</code> mit Kardinalität <code>1</code>, dass jede Instanz von <code>DiagnosticClearResetEmissionRelatedInfo</code> exakt einer Klasseninstanz <code>DiagnosticClearResetEmissionRelatedInfoClass</code> zugewiesen sein muss. Entwickler und Generatoren von Diagnosekonfigurationen müssen sicherstellen, dass die Typkompatibilität zwischen Service-Instanz und zugehöriger Service-Klasse gewahrt bleibt und Zugriffsprüfungen konsistent mit <code>DiagnosticAccessPermissionValidityEnum</code> parametriert werden.</p>"}, {"id": "FIG-38a0f7d70a0fd05e", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm für das AUTOSAR Diagnostic Extract Template (DEXT). Das Diagramm spezifiziert die metamodellbasierte Modellierung des OBD-Dienstes Mode 0x04 (Clear/Reset Emission-Related Diagnostic Information) im Kontext des Diagnostic Communication Managers (Dcm). Es veranschaulicht die Spezialisierung generischer Diagnosedienst- und Diagnoseklassenstrukturen für spezifische OBD-Dienste sowie deren Verknüpfung zu Zugriffsberechtigungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und deren Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>DiagnosticCommonElement</code>: Abstrakter gemeinsamer Basistyp für Diagnose-Elemente.\n</li><li><code>DiagnosticServiceInstance</code> (spezialisiert <code>DiagnosticCommonElement</code>): Repräsentiert eine konkrete Instanz eines Diagnosedienstes. Besitzt eine gerichtete Assoziation <code>+serviceClass</code> (Kardinalität <code>0..1</code>, Stereotyp «atpAbstract») zur Metaklasse <code>DiagnosticServiceClass</code> sowie eine Assoziation <code>+accessPermission</code> (Kardinalität <code>0..1</code>) zu <code>DiagnosticAccessPermission</code>.\n</li><li><code>DiagnosticServiceClass</code> (spezialisiert <code>DiagnosticCommonElement</code>): Repräsentiert die funktionale Klassendefinition des Diagnosedienstes. Enthält das Attribut <code>+accessPermissionValidity : DiagnosticAccessPermissionValidityEnum</code> und referenziert <code>DiagnosticAccessPermission</code> über die gerichtete Assoziation <code>+accessPermission</code> (Kardinalität <code>0..1</code>).\n</li><li><code>DiagnosticAccessPermission</code> (spezialisiert <code>DiagnosticCommonElement</code>): Definiert die Zugriffsbedingungen für den Dienst.\n</li><li><code>DiagnosticClearResetEmissionRelatedInfo</code> (spezialisiert <code>DiagnosticServiceInstance</code>): Konkrete Modellierungsklasse für eine Instanz des OBD-Modus 0x04. Definiert eine gerichtete Assoziation <code>+clearResetEmissionRelatedDiagnosticInfoClass</code> mit Multiplizität <code>1</code> zur Klasse <code>DiagnosticClearResetEmissionRelatedInfoClass</code>, welche die geerbte Assoziation <code>{redefines serviceClass}</code> redefiniert.\n</li><li><code>DiagnosticClearResetEmissionRelatedInfoClass</code> (spezialisiert <code>DiagnosticServiceClass</code>): Spezifische Serviceklasse für das Löschen bzw. Zurücksetzen emissionsbezogener Diagnoseinformationen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite Modellierung von dynamischen Sequenzen, Zustandsübergängen oder Kontrollflüssen. Das Diagramm beschreibt die Deklarations- und Konfigurationsstruktur eines OBD-Modus 0x04 im AUTOSAR Diagnostic Extract. Der Dienstaufruf im Steuergerät führt über die instanziierte Konfiguration (<code>DiagnosticClearResetEmissionRelatedInfo</code>) zur Dienstklasse (<code>DiagnosticClearResetEmissionRelatedInfoClass</code>), wobei die statische Zuordnung der Berechtigungen über <code>DiagnosticAccessPermission</code> zur Absicherung herangezogen wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der AUTOSAR-DEXT-Metamodellstruktur für OBD Mode 0x04 gemäß <code>[TPS_DEXT_01128]</code>. Die Modellierung erzwingt über die Redefinition <code>{redefines serviceClass}</code> mit Kardinalität <code>1</code>, dass jede Instanz von <code>DiagnosticClearResetEmissionRelatedInfo</code> exakt einer Klasseninstanz <code>DiagnosticClearResetEmissionRelatedInfoClass</code> zugewiesen sein muss. Entwickler und Generatoren von Diagnosekonfigurationen müssen sicherstellen, dass die Typkompatibilität zwischen Service-Instanz und zugehöriger Service-Klasse gewahrt bleibt und Zugriffsprüfungen konsistent mit <code>DiagnosticAccessPermissionValidityEnum</code> parametriert werden.</p>"}, {"id": "FIG-cabbc47d728d2627", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm für das AUTOSAR Diagnostic Extract Template (DEXT). Das Diagramm spezifiziert die metamodellbasierte Modellierung des OBD-Dienstes Mode 0x04 (Clear/Reset Emission-Related Diagnostic Information) im Kontext des Diagnostic Communication Managers (Dcm). Es veranschaulicht die Spezialisierung generischer Diagnosedienst- und Diagnoseklassenstrukturen für spezifische OBD-Dienste sowie deren Verknüpfung zu Zugriffsberechtigungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und deren Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>DiagnosticCommonElement</code>: Abstrakter gemeinsamer Basistyp für Diagnose-Elemente.\n</li><li><code>DiagnosticServiceInstance</code> (spezialisiert <code>DiagnosticCommonElement</code>): Repräsentiert die Instanz eines Diagnosedienstes. Besitzt eine gerichtete Assoziation <code>+serviceClass</code> (Kardinalität <code>0..1</code>, Stereotyp «atpAbstract») zur Metaklasse <code>DiagnosticServiceClass</code>.\n</li><li><code>DiagnosticServiceClass</code> (spezialisiert <code>DiagnosticCommonElement</code>): Repräsentiert die funktionale Klassendefinition des Diagnosedienstes. Besitzt eine Assoziation <code>+accessPermission</code> (Kardinalität <code>0..1</code>) zu <code>DiagnosticAccessPermission</code>.\n</li><li><code>DiagnosticAccessPermission</code> (spezialisiert <code>DiagnosticCommonElement</code>): Metaklasse zur Definition von Berechtigungsstrukturen für Diagnosezugriffe.\n</li><li><code>DiagnosticClearResetEmissionRelatedInfo</code> (spezialisiert <code>DiagnosticServiceInstance</code>): Konkrete Service-Instanz für OBD Mode 0x04. Referenziert über die Assoziation <code>+clearResetEmissionRelatedDiagnosticInfoClass</code> mit Kardinalität <code>0..1</code> und Eigenschaft <code>{redefines serviceClass}</code> die Klasse <code>DiagnosticClearResetEmissionRelatedInfoClass</code>.\n</li><li><code>DiagnosticClearResetEmissionRelatedInfoClass</code> (spezialisiert <code>DiagnosticServiceClass</code>): Spezifische Funktionsklasse zur Ausführung des Lösch- und Rücksetzvorgangs emissionsbezogener Diagnosedaten.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite Modellierung von dynamischen Sequenzen, Zustandsübergängen oder Kontrollflüssen. Das Diagramm beschreibt die Deklarations- und Konfigurationsstruktur eines OBD-Modus 0x04 im AUTOSAR Diagnostic Extract. Der Dienstaufruf im Steuergerät führt über die instanziierte Konfiguration (<code>DiagnosticClearResetEmissionRelatedInfo</code>) zur Dienstklasse (<code>DiagnosticClearResetEmissionRelatedInfoClass</code>), wobei die statische Zuordnung der Berechtigungen über <code>DiagnosticAccessPermission</code> zur Absicherung herangezogen wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der AUTOSAR-DEXT-Metamodellstruktur für OBD Mode 0x04. Durch die Kardinalität <code>0..1</code> bei <code>clearResetEmissionRelatedDiagnosticInfoClass</code> ist die Zuordnung zu einer <code>DiagnosticClearResetEmissionRelatedInfoClass</code> optional, muss jedoch bei Vorhandensein die Redefinition von <code>serviceClass</code> einhalten. Die direkte Assoziation von <code>DiagnosticServiceInstance</code> zu <code>DiagnosticAccessPermission</code> sowie das Attribut <code>accessPermissionValidity</code> an <code>DiagnosticServiceClass</code> sind nicht mehr Bestandteil dieses Modellierungsausschnitts; Zugriffsrechte verbleiben auf Ebene der Serviceklasse. DEXT-Validatoren müssen die gelockerte Multiplizität (0..1) berücksichtigen.</p>"}], "trans": [{"from": "FIG-a6c9b7febd62aaa9", "to": "FIG-62ebbe518190f195", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-62ebbe518190f195", "to": "FIG-38a0f7d70a0fd05e", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-38a0f7d70a0fd05e", "to": "FIG-cabbc47d728d2627", "fr": "R19-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>DiagnosticClearResetEmissionRelatedInfo</code>: Kardinalität der Assoziation <code>clearResetEmissionRelatedDiagnosticInfoClass</code> von <code>1</code> auf <code>0..1</code> geändert.\n</li><li><code>DiagnosticAccessPermission</code>: Assoziation <code>accessPermission</code> (Kardinalität <code>0..1</code>) von <code>DiagnosticServiceInstance</code> entfallen.\n</li><li><code>DiagnosticServiceClass</code>: Attribut <code>accessPermissionValidity : DiagnosticAccessPermissionValidityEnum</code> entfallen.\n</li><li>Diagrammlayout von zweizeiliger Anordnung zu linearer horizontaler Ausrichtung der oberen Klassenebene umstrukturiert.\n</li></ul>"}]};
